/**
 * Memory Database
 *
 * In-memory implementation of database repositories.
 * Useful for testing and development.
 */

import { randomUUID } from 'crypto';
import type { Message, ToolCall, SessionStatus } from '../types';
import type {
  Conversation,
  CreateConversation,
  DBMessage,
  CreateMessage,
  DBSession,
  CreateSession,
  ConversationRepository,
  MessageRepository,
  SessionRepository,
  Repositories,
} from './types';

/**
 * In-memory conversation repository
 */
export class MemoryConversationRepository implements ConversationRepository {
  private conversations: Map<string, Conversation> = new Map();

  async list(userId: string): Promise<Conversation[]> {
    return Array.from(this.conversations.values())
      .filter(c => c.userId === userId)
      .sort((a, b) => b.updatedAt - a.updatedAt);
  }

  async getById(id: string): Promise<Conversation | null> {
    return this.conversations.get(id) || null;
  }

  async create(data: CreateConversation): Promise<Conversation> {
    const now = Date.now();
    const conversation: Conversation = {
      id: randomUUID(),
      userId: data.userId,
      title: data.title,
      projectId: data.projectId,
      isPinned: false,
      createdAt: now,
      updatedAt: now,
    };
    this.conversations.set(conversation.id, conversation);
    return conversation;
  }

  async update(id: string, data: Partial<Conversation>): Promise<void> {
    const existing = this.conversations.get(id);
    if (existing) {
      this.conversations.set(id, {
        ...existing,
        ...data,
        updatedAt: Date.now(),
      });
    }
  }

  async updateTitle(id: string, title: string): Promise<void> {
    await this.update(id, { title });
  }

  async delete(id: string): Promise<void> {
    this.conversations.delete(id);
  }

  clear(): void {
    this.conversations.clear();
  }
}

/**
 * In-memory message repository
 */
export class MemoryMessageRepository implements MessageRepository {
  private messages: Map<string, DBMessage> = new Map();

  async getByConversation(conversationId: string): Promise<DBMessage[]> {
    return Array.from(this.messages.values())
      .filter(m => m.conversationId === conversationId)
      .sort((a, b) => a.createdAt - b.createdAt);
  }

  async getById(id: string): Promise<DBMessage | null> {
    return this.messages.get(id) || null;
  }

  async create(data: CreateMessage): Promise<DBMessage> {
    const message: DBMessage = {
      id: randomUUID(),
      conversationId: data.conversationId,
      role: data.role,
      content: data.content,
      reasoning: data.reasoning,
      toolCalls: data.toolCalls,
      toolCallId: data.toolCallId,
      createdAt: Date.now(),
      inputTokens: data.inputTokens,
      outputTokens: data.outputTokens,
      sources: data.sources,
      attachments: data.attachments,
    };
    this.messages.set(message.id, message);
    return message;
  }

  async saveAssistantMessage(data: {
    conversationId: string;
    content: string;
    reasoning?: string;
    toolCalls?: ToolCall[];
    inputTokens?: number;
    outputTokens?: number;
  }): Promise<DBMessage> {
    return this.create({
      conversationId: data.conversationId,
      role: 'assistant',
      content: data.content,
      reasoning: data.reasoning,
      toolCalls: data.toolCalls,
      inputTokens: data.inputTokens,
      outputTokens: data.outputTokens,
    });
  }

  async saveToolMessage(data: {
    conversationId: string;
    toolCallId: string;
    toolName: string;
    content: string;
  }): Promise<DBMessage> {
    return this.create({
      conversationId: data.conversationId,
      role: 'tool',
      content: data.content,
      toolCallId: data.toolCallId,
    });
  }

  clear(): void {
    this.messages.clear();
  }
}

/**
 * In-memory session repository
 */
export class MemorySessionRepository implements SessionRepository {
  private sessions: Map<string, DBSession> = new Map();

  async getById(id: string): Promise<DBSession | null> {
    return this.sessions.get(id) || null;
  }

  async getByStreamId(streamId: string): Promise<DBSession | null> {
    return Array.from(this.sessions.values()).find(s => s.streamId === streamId) || null;
  }

  async getActive(conversationId: string): Promise<DBSession | null> {
    return Array.from(this.sessions.values()).find(
      s => s.conversationId === conversationId &&
        (s.status === 'pending' || s.status === 'running' || s.status === 'tool_loop')
    ) || null;
  }

  async create(data: CreateSession): Promise<DBSession> {
    const now = Date.now();
    const session: DBSession = {
      id: randomUUID(),
      conversationId: data.conversationId,
      userId: data.userId,
      streamId: data.streamId,
      status: 'pending',
      toolLoopDepth: 0,
      createdAt: now,
      lastActivityAt: now,
    };
    this.sessions.set(session.id, session);
    return session;
  }

  async updateStatus(id: string, status: SessionStatus, extra?: Partial<DBSession>): Promise<void> {
    const existing = this.sessions.get(id);
    if (existing) {
      this.sessions.set(id, {
        ...existing,
        ...extra,
        status,
        lastActivityAt: Date.now(),
      });
    }
  }

  async complete(id: string, data: {
    assistantMessageId?: string;
    accumulatedContent?: string;
    accumulatedReasoning?: string;
    inputTokens?: number;
    outputTokens?: number;
  }): Promise<void> {
    const existing = this.sessions.get(id);
    if (existing) {
      this.sessions.set(id, {
        ...existing,
        ...data,
        status: 'completed',
        completedAt: Date.now(),
        lastActivityAt: Date.now(),
      });
    }
  }

  clear(): void {
    this.sessions.clear();
  }
}

/**
 * Create in-memory repositories bundle
 */
export function createMemoryRepositories(): Repositories {
  return {
    conversations: new MemoryConversationRepository(),
    messages: new MemoryMessageRepository(),
    sessions: new MemorySessionRepository(),
  };
}
